import test from 'node:test';
import assert from 'node:assert/strict';
import { RunnerModel, RULES, OBSTACLE_WIDTHS, difficultyAt } from '../src/model.ts';

const DT = 1 / 120; // same fixed step as src/main.ts
const GROUND = { platforms: false, encounters: false } as const; // isolated ground regression
const F = RULES.floor;
type Kind = 'block' | 'beam' | 'tower' | 'long' | 'pit' | 'food' | 'gold';
type State = 'normal' | 'exhausted' | 'boost';
// Item geometry as generated by src/model.ts: [y, default width, height].
const DIMS: Record<Kind, [number, number, number]> = {
  block: [F - 64, 60, 64], tower: [F - 190, 60, 190], long: [F - 46, 175, 46], pit: [F, 170, 170],
  beam: [84, 160, F - 44 - 84], food: [F - 48, 32, 32], gold: [F - 48, 32, 32],
};
const SPEED: Record<State, number> = { normal: RULES.speed, exhausted: RULES.exhaustedSpeed, boost: RULES.boostSpeed };

// Empty course: the authored course is switched off, each test places what it needs.
function quiet(seed = 123): RunnerModel { const m = new RunnerModel(seed, false, GROUND); m.start(); return m; }
function put(m: RunnerModel, kind: Kind, x: number, w = DIMS[kind][1]) {
  m.items.push({ id: m.items.length + 1000, x, y: DIMS[kind][0], w, h: DIMS[kind][2], kind, used: false });
}
function run(m: RunnerModel, seconds: number, before?: (m: RunnerModel) => void) {
  for (let i = 0; i < Math.round(seconds / DT) && m.phase === 'running'; i++) { before?.(m); m.step(DT); }
}
// Keeps a state fixed the way a test needs (stamina topped up so draining never changes it).
function hold(m: RunnerModel, state: State) { m.gap = 30; m.stamina = 80; m.exhausted = state === 'exhausted'; m.boost = state === 'boost' ? 1 : 0; }

// One obstacle 20m ahead. `jumpAhead`: press jump when the obstacle centre is that many metres ahead
// (null = no jump). `secondDelay`: press jump again that many seconds after the first press.
function attempt(kind: Kind, w: number, state: State, jumpAhead: number | null, secondDelay: number | null, crouchHold = false) {
  const m = quiet(); const x = m.distance + 20; put(m, kind, x, w);
  let t0 = -1, second = false, fell = false;
  for (let i = 0; i < 120 * 14 && m.distance < x + 6 && m.phase === 'running'; i++) {
    hold(m, state);
    const ahead = x - m.distance;
    if (t0 < 0 && jumpAhead !== null && ahead <= jumpAhead) { m.jump(); t0 = m.elapsed; }
    if (t0 >= 0 && !second && secondDelay !== null && m.elapsed - t0 >= secondDelay) { m.jump(); second = true; }
    m.crouch = crouchHold && ahead < 5 && ahead > -5;
    m.step(DT);
    if (m.rescue) fell = true;
  }
  return { clean: m.hits === 0 && !fell && m.phase === 'running', hits: m.hits, fell };
}
// Seconds of timing that clear the obstacle with the best second-jump delay (or a single jump).
const cache = new Map<string, { single: number; double: number; bestDelay: number }>();
function windows(kind: Kind, w: number, state: State) {
  const key = `${kind}${w}${state}`; const hit = cache.get(key); if (hit) return hit;
  const count = (d: number | null) => { let n = 0; for (let a = 0.2; a <= 9; a += 0.04) if (attempt(kind, w, state, a, d).clean) n++; return n * 0.04 / SPEED[state]; };
  const single = count(null); let double = 0, bestDelay = 0;
  for (let d = 0.1; d <= 1.2001; d += 0.1) { const v = count(d); if (v > double) { double = v; bestDelay = d; } }
  const r = { single, double, bestDelay }; cache.set(key, r); return r;
}

// ---------------------------------------------------------------- rules contract
test('rules contract: the agreed v6 numbers', () => {
  assert.deepEqual(
    [RULES.staminaDrain, RULES.food, RULES.goldFood, RULES.recover, RULES.boostSeconds, RULES.boostSpeed, RULES.hitCost, RULES.hitInvulnerability, RULES.goldChance],
    [4, 20, 25, 12, 1, 9, 3, 0.5, 0.1]);
  assert.deepEqual([RULES.playerHeight, RULES.playerWidth, RULES.halfHitWidth, RULES.crouchHeight, RULES.floor, RULES.jumpVelocity, RULES.gravity],
    [82, 64, 24, 36, 460, -760, 1900]);
  assert.ok(RULES.food >= RULES.recover && RULES.goldFood >= RULES.recover, 'any food must clear the exhausted latch');
  assert.equal(RULES.boostSpeed / RULES.speed, 1.5);
});

test('initial state; ready phase ignores steps and input; empty course option', () => {
  const m = new RunnerModel(123, false, GROUND);
  assert.deepEqual([m.phase, m.gap, m.stamina, m.exhausted, m.boost, m.hits, m.items.length, m.rescue], ['ready', 30, 100, false, 0, 0, 0, null]);
  m.step(1); m.jump(); assert.equal(m.distance, 0); assert.equal(m.phase, 'ready');
  assert.ok(new RunnerModel(13579, true, GROUND).items.length > 0);
});

test('speed states: boost wins over exhausted over normal', () => {
  const m = quiet(); assert.equal(m.speed, 6);
  m.exhausted = true; assert.equal(m.speed, RULES.exhaustedSpeed);
  m.boost = 1; assert.equal(m.speed, 9);
});

// ---------------------------------------------------------------- stamina, food, gold
test('stamina drains 4/s; reaching 0 latches exhausted after 25s', () => {
  const m = quiet(); run(m, 10); assert.ok(Math.abs(m.stamina - 60) < 0.1); assert.equal(m.exhausted, false);
  run(m, 14.9); assert.ok(m.stamina > 0); assert.equal(m.exhausted, false);
  run(m, .2); assert.equal(m.stamina, 0); assert.equal(m.exhausted, true);
});

test('normal speed keeps the gap; exhausted shrinks 1.8/s and a 30m gap is caught in 16.7s', () => {
  const m = quiet(); run(m, 5); assert.equal(m.gap, 30);
  const e = quiet(); e.stamina = 0; let t = 0;
  while (e.phase === 'running' && t < 30) { e.step(DT); t += DT; }
  assert.equal(e.phase, 'over'); assert.equal(e.gap, 0); assert.ok(t > 16.5 && t < 16.9, `caught at ${t}`);
});

test('food +20 and gold +25 (capped at 100), both clear exhaustion, counted once', () => {
  const m = quiet(); m.stamina = 0; m.exhausted = true; put(m, 'food', m.distance + 0.5);
  run(m, 0.4); assert.equal(m.foods, 1); assert.ok(m.stamina >= 12 && m.stamina <= 20); assert.equal(m.exhausted, false);
  const g = quiet(); g.stamina = 0; g.exhausted = true; g.eat('gold'); assert.equal(g.stamina, 25); assert.equal(g.exhausted, false);
  const f = quiet(); f.stamina = 95; f.eat('food'); assert.equal(f.stamina, 100); f.eat('gold'); assert.equal(f.stamina, 100);
});

test('exhaustion stays latched while stamina is 1-11 (hysteresis threshold is 12)', () => {
  const m = quiet(); m.exhausted = true; m.stamina = 8; run(m, 0.5);
  assert.equal(m.exhausted, true); assert.ok(m.stamina > 0 && m.stamina < 8); assert.equal(m.speed, RULES.exhaustedSpeed);
});

test('gold: bonus 30 (100 at the gap cap), 1s boost at 9m/s, refresh not stack', () => {
  const m = quiet(); put(m, 'gold', m.distance + 0.3); run(m, 0.1);
  assert.equal(m.bonus, 30); assert.ok(m.boost > 0.85 && m.boost <= 1); assert.equal(m.speed, 9);
  run(m, 0.5); const mid = m.boost; assert.ok(mid > 0.3 && mid < 0.5);
  put(m, 'gold', m.distance + 0.2); run(m, 0.1); assert.ok(m.boost > 0.85 && m.boost <= 1, `refreshed to ${m.boost}`);
  run(m, 1.05); assert.equal(m.boost, 0); assert.equal(m.speed, 6);
  const c = quiet(); c.gap = 60; c.eat('gold'); assert.equal(c.bonus, 100);
});

test('gold at stamina 0: boost speed, then the exhausted state is rebuilt only if stamina drops to 0 again', () => {
  const m = quiet(); m.stamina = 0; m.exhausted = true; m.eat('gold');
  assert.equal(m.stamina, 25); assert.equal(m.exhausted, false); assert.equal(m.speed, 9);
  run(m, 1.1); assert.equal(m.boost, 0); assert.equal(m.exhausted, false); assert.equal(m.speed, 6);
  // boundary: exhausted again once stamina is set to 0 and a step is taken
  m.stamina = 0; run(m, 0.05); assert.equal(m.exhausted, true); assert.equal(m.speed, RULES.exhaustedSpeed);
});

test('boost: gap grows +3/s and is capped at 60', () => {
  const m = quiet(); m.eat('gold'); const g0 = m.gap; run(m, 0.5);
  assert.ok(Math.abs(m.gap - (g0 + 1.5)) < 0.05);
  const c = quiet(); c.gap = 59.9; c.eat('gold'); run(c, 1); assert.equal(c.gap, 60);
});

// ---------------------------------------------------------------- hits, protection, boost immunity
test('hit: gap -3 once, hitFlash 0.5s, obstacle consumed only by a real hit, distance never goes backwards', () => {
  const m = quiet(); put(m, 'block', m.distance + 0.2); let last = m.distance, back = false;
  for (let i = 0; i < 120; i++) { m.step(DT); if (m.distance < last) back = true; last = m.distance; }
  assert.equal(back, false); assert.equal(m.hits, 1); assert.equal(m.gap, 27);
  assert.ok(m.items.length === 0 || m.items.every(i => i.used));
  const h = quiet(); put(h, 'block', h.distance + 0.2); run(h, 0.1); assert.ok(h.hitFlash > 0.35 && h.hitFlash <= 0.5); assert.equal(h.invulnerable, true);
  run(h, 0.5); assert.equal(h.hitFlash, 0); assert.equal(h.invulnerable, false);
});

test('hit protection: an obstacle touched while protected is NOT consumed and hits as soon as protection ends', () => {
  const m = quiet(); put(m, 'block', m.distance + 1.25); put(m, 'block', m.distance + 3.1);
  const second = m.items[1];
  run(m, 0.3); assert.equal(m.hits, 1); assert.equal(m.gap, 27); assert.equal(second.used, false);
  run(m, 0.12); // now overlapping the second block while still protected
  assert.ok(m.hitFlash > 0); assert.equal(m.hits, 1); assert.equal(second.used, false, 'protected contact must not consume');
  run(m, 0.2); assert.equal(m.hits, 2); assert.equal(second.used, true); assert.equal(m.gap, 24);
});

test('boost ignores hazards and does not consume them; overlap after boost ends is a normal hit', () => {
  const m = quiet(); put(m, 'long', m.distance + 0.1, 210); m.boost = 0.05;
  run(m, 0.04); assert.equal(m.hits, 0); assert.equal(m.items[0].used, false);
  run(m, 0.1); assert.equal(m.boost, 0); assert.equal(m.hits, 1); assert.equal(m.items[0].used, true);
});

test('a hit that empties the gap ends the run', () => {
  const m = quiet(); m.gap = 2; put(m, 'block', m.distance + 0.2); run(m, 0.2);
  assert.equal(m.phase, 'over'); assert.equal(m.gap, 0);
});

// ---------------------------------------------------------------- pause
test('pause freezes distance/gap/stamina/boost/hitFlash/time; input ignored; resume continues', () => {
  const m = quiet(); m.eat('gold'); m.hitFlash = 0.4; run(m, 0.2);
  const snap = () => [m.distance, m.gap, m.stamina, m.boost, m.hitFlash, m.elapsed, m.y];
  const before = snap(); m.crouch = true; m.pause();
  assert.equal(m.phase, 'paused'); assert.equal(m.crouch, false);
  m.jump(); for (let i = 0; i < 600; i++) m.step(DT);
  assert.deepEqual(snap(), before);
  m.start(); run(m, 0.3); assert.ok(m.distance > before[0]); assert.equal(m.events.filter(e => e === '점프').length, 0);
});

test('pause only works while running; a finished run cannot be restarted with start()', () => {
  const m = new RunnerModel(1, false, GROUND); m.pause(); assert.equal(m.phase, 'ready');
  const o = quiet(); o.gap = 0.01; o.stamina = 0; run(o, 1); assert.equal(o.phase, 'over'); o.pause(); o.start(); assert.equal(o.phase, 'over');
});

// ---------------------------------------------------------------- jump physics
function arc(exhausted: boolean, mid?: (m: RunnerModel, i: number) => void) {
  const m = quiet(); m.exhausted = exhausted; m.jump(); const ys: number[] = [];
  for (let i = 0; i < 120 * 4; i++) { m.stamina = 50; m.gap = 30; mid?.(m, i); m.step(DT); ys.push(m.y); if (i > 5 && m.grounded) break; }
  return { ys, m };
}
test('jump physics: height ~152px, double jump higher, third press ignored, clean landing', () => {
  const n = arc(false); const peak = F - Math.min(...n.ys);
  assert.ok(Math.abs(peak - 760 * 760 / (2 * 1900)) < 4, `peak ${peak}`);
  const m = quiet(); m.jump(); run(m, 0.05); assert.equal(m.jumps, 1);
  run(m, 0.3); m.jump(); run(m, 0.05); assert.equal(m.jumps, 2);
  let top = m.y; for (let i = 0; i < 160; i++) { m.step(DT); top = Math.min(top, m.y); }
  assert.ok(F - top > peak + 60);
  const t = quiet(); t.jump(); run(t, 0.1); t.jump(); run(t, 0.1); t.jump(); run(t, 0.1);
  assert.equal(t.events.filter(e => e === '점프' || e === '더블 점프').length, 2);
  run(t, 3); assert.equal(t.y, F); assert.equal(t.jumps, 0); assert.equal(t.vy, 0);
});

test('exhausted jump: same height AND same air time as a normal jump (jump does not depend on run speed)', () => {
  const n = arc(false), e = arc(true); const top = (ys: number[]) => F - Math.min(...ys);
  assert.ok(Math.abs(top(n.ys) - top(e.ys)) < 1e-6);
  assert.deepEqual(e.ys, n.ys);
  assert.ok(Math.abs(n.ys.length * DT - 0.8) < 0.05, `air time ${n.ys.length * DT}`);
  // horizontal reach follows the run speed: 3.6m/s -> shorter than 6m/s, same time
  assert.ok(e.m.distance < n.m.distance);
});


test('gravity is fixed at takeoff: food, boost start and boost end in the air do not change the arc', () => {
  const control = arc(true).ys;
  const ate = arc(true, (m, i) => { if (i === 40) { m.exhausted = true; m.eat('food'); } }).ys;
  const boostStart = arc(true, (m, i) => { if (i === 40) m.eat('gold'); }).ys;
  const boostEnd = arc(true, (m, i) => { if (i === 40) m.boost = 0.05; }).ys;
  assert.deepEqual(ate, control); assert.deepEqual(boostStart, control); assert.deepEqual(boostEnd, control);
});

test('after landing, gravity scale resets; exhausted double jump lands cleanly', () => {
  const { m } = arc(true, (mm, i) => { if (i === 30) mm.eat('food'); });
  assert.ok(m.grounded); m.exhausted = false; m.boost = 0; const n = arc(false);
  m.jump(); let top = m.y; for (let i = 0; i < 160; i++) { m.stamina = 50; m.step(DT); top = Math.min(top, m.y); }
  assert.ok(Math.abs((F - top) - (F - Math.min(...n.ys))) < 2);
  const d = quiet(); d.exhausted = true; d.jump(); run(d, 0.4, x => { x.stamina = 50; }); d.jump(); run(d, 3, x => { x.stamina = 50; x.gap = 30; });
  assert.ok(d.grounded); assert.equal(d.jumps, 0);
});

// ---------------------------------------------------------------- crouch and beam
test('crouch is 36px on the ground only; beam leaves 8px of room above the crouched player', () => {
  const m = quiet(); assert.equal(m.height, 82); m.crouch = true; assert.equal(m.height, 36);
  m.jump(); run(m, 0.1, mm => { mm.crouch = true; }); assert.equal(m.height, 82);
  const beam = DIMS.beam; const bottom = beam[0] + beam[2];
  assert.equal(bottom, F - 44); assert.ok((F - RULES.crouchHeight) - bottom >= 6, 'crouch margin');
  assert.ok(F - RULES.playerHeight < bottom, 'standing must collide');
});

test('beam: standing hits, crouching clears, releasing crouch under the beam hits immediately', () => {
  for (const w of [100, 160, 220]) {
    assert.equal(attempt('beam', w, 'normal', null, null, false).clean, false, `stand ${w}`);
    for (const s of ['normal', 'exhausted', 'boost'] as State[]) {
      const r = attempt('beam', w, s, null, null, true);
      if (s === 'boost') assert.equal(r.hits, 0); else assert.equal(r.clean, true, `crouch ${w} ${s}`);
    }
  }
  const m = quiet(); const x = m.distance + 20; put(m, 'beam', x, 220);
  while (m.distance < x - 0.2) { m.crouch = true; m.step(DT); }
  assert.equal(m.hits, 0);
  const gapBefore = m.gap;
  m.crouch = false; m.step(DT);
  assert.equal(m.height, RULES.playerHeight);
  assert.equal(m.hits, 1);
  assert.equal(m.gap, gapBefore - RULES.hitCost);
  assert.equal(m.hitFlash, RULES.hitInvulnerability);
  run(m, 1);
  assert.equal(m.hits, 1, 'the same beam must not hit twice');
});

test('beam is attached to the ceiling: no jump timing (single or double, any delay) passes it', () => {
  for (const w of [100, 220]) for (const s of ['normal', 'exhausted'] as State[]) {
    for (let a = 0.2; a <= 8; a += 0.1) for (const d of [null, 0.2, 0.4, 0.6]) assert.equal(attempt('beam', w, s, a, d).clean, false, `${w} ${s} ${a} ${d}`);
  }
});

// ---------------------------------------------------------------- hazards by kind, width and state
const CASES: [Kind, number][] = [['block', 48], ['block', 64], ['tower', 44], ['tower', 52], ['long', 120], ['long', 145], ['long', 170], ['pit', 120], ['pit', 160], ['pit', 200]];
test('real collisions: walking into any ground hazard hurts or drops you', () => {
  for (const [k, w] of CASES) assert.equal(attempt(k, w, 'normal', null, null).clean, false, `${k}${w}`);
});

test('jump timing windows per obstacle, width and speed state (report + intent checks)', () => {
  // Boost is not measured for blocks/towers/longs: boost makes the player immune to those hazards.
  const rows: string[] = [], states: State[] = ['normal', 'exhausted'];
  for (const [k, w] of CASES) for (const st of (k === 'pit' ? ['normal', 'exhausted', 'boost'] : states) as State[]) {
    const r = windows(k, w, st);
    rows.push(`${k}${w} ${st}: single ${r.single.toFixed(2)}s, double ${r.double.toFixed(2)}s (second press ${r.bestDelay.toFixed(1)}s after the first)`);
  }
  console.log(rows.join('\n'));
  const W = windows;
  // widest allowed widths are the hardest cases: block 64, tower 64, long 210, pit 220, beam 220 (crouch)
  for (const w of [48, 64]) {
    assert.ok(W('block', w, 'normal').single >= 0.15, `block${w} normal single`);
    for (const st of states) assert.ok(W('block', w, st).double >= 0.5, `block${w} ${st} double`);
  }
  // Jump arcs do not depend on run speed, so an exhausted runner (4.2m/s) covers less ground per jump: windows shrink but stay open.
  for (const w of [44, 52]) for (const st of states) { assert.equal(W('tower', w, st).single, 0); assert.ok(W('tower', w, st).double >= (st === 'normal' ? 0.2 : 0.1), `tower${w} ${st}`); }
  for (const w of [120, 145, 170]) for (const st of states) {
    if (w >= 145) assert.equal(W('long', w, st).single, 0, `long${w} ${st} single`); assert.ok(W('long', w, st).double >= (st === 'normal' ? 0.4 : 0.2), `long${w} ${st} double`);
  }
  for (const w of [120, 160, 200]) for (const st of ['normal', 'exhausted', 'boost'] as State[]) {
    const r = W('pit', w, st); assert.ok(Math.max(r.single, r.double) >= 0.2, `pit${w} ${st}`);
  }
});

test('boost lets a player run through hazards for its 1s only', () => {
  const m = quiet(); put(m, 'long', m.distance + 5, 210); m.eat('gold'); run(m, 0.5); assert.equal(m.hits, 0);
  const n = quiet(); put(n, 'long', n.distance + 20, 210); n.eat('gold'); run(n, 1.1); assert.equal(n.boost, 0); assert.equal(n.hits, 0);
});

// ---------------------------------------------------------------- pits and rescue
function fall(w: number, state: State, before?: (m: RunnerModel) => void) {
  const m = quiet(); const x = m.distance + 10; put(m, 'pit', x, w); before?.(m);
  let fellAt = -1, landed = -1, hitsAtFall = 0;
  for (let i = 0; i < 120 * 12 && m.phase === 'running'; i++) {
    const wasRescue = m.rescue !== null;
    if (state !== 'normal') { m.exhausted = state === 'exhausted'; if (state === 'boost') m.boost = 1; }
    m.stamina = 80; m.step(DT);
    if (!wasRescue && m.rescue && fellAt < 0) { fellAt = i; hitsAtFall = m.hits; }
    if (wasRescue && !m.rescue) { landed = i; break; }
  }
  return { m, fellAt, landed, hitsAtFall };
}

test('pit: walking in drops you, one hit (-3 gap), a 0.9s rescue puts you on safe ground past the pit', () => {
  for (const w of [120, 170, 220]) for (const s of ['normal', 'exhausted'] as State[]) {
    const r = fall(w, s);
    assert.ok(r.fellAt > 0, `fell ${w} ${s}`); assert.equal(r.hitsAtFall, 1, `hit ${w} ${s}`);
    assert.ok(Math.abs((r.landed - r.fellAt) * DT - RULES.rescueSeconds) < 0.05, `rescue time ${(r.landed - r.fellAt) * DT}`);
    const m = r.m; assert.equal(m.rescue, null); assert.equal(m.y, F); assert.ok(m.grounded);
    const pit = m.items.find(i => i.kind === 'pit')!; assert.ok(m.distance > pit.x + pit.w / 2 / RULES.scale, 'landed beyond the pit');
    assert.equal(m.phase, 'running'); assert.ok(m.gap > 0 && m.gap < 30, `gap ${m.gap}`);
  }
});

test('pit: no penalty while protected (hit protection or boost), rescue still happens', () => {
  const p = fall(120, 'normal', m => { m.hitFlash = 5; }); assert.ok(p.fellAt > 0); assert.equal(p.m.hits, 0); assert.equal(p.m.gap, 30);
  const b = fall(120, 'boost'); assert.ok(b.fellAt > 0, 'boost still falls into a pit'); assert.equal(b.m.hits, 0);
});

test('rescue: invulnerable, hazards ignored, chase and stamina keep running, input ignored, distance only moves forward', () => {
  const m = quiet(); put(m, 'pit', m.distance + 8, 220); put(m, 'block', m.distance + 13); put(m, 'long', m.distance + 17, 210);
  let n = 0, last = m.distance, back = false, seen = false, st0 = 0;
  for (let i = 0; i < 120 * 8 && m.phase === 'running'; i++) {
    m.stamina = Math.max(m.stamina, 40);
    if (m.rescue && !seen) { seen = true; st0 = m.stamina; }
    if (m.rescue) { assert.equal(m.invulnerable, true); m.jump(); n++; }
    m.step(DT); if (m.distance < last - 1e-9) back = true; last = m.distance;
  }
  assert.ok(seen); assert.equal(back, false); assert.ok(n > 100 && n < 115);
  assert.ok(m.hits <= 2, `hits ${m.hits}`); // the pit fall plus at most one later real hit
});

test('rescue landing is always clear of every hazard, including adjoining pits and obstacles right behind the pit', () => {
  let checked = 0;
  for (const w of [120, 170, 220]) for (const s of ['normal', 'exhausted', 'boost'] as State[]) for (let off = 0; off <= 14; off += 1) for (const next of ['pit', 'block', 'long', 'tower'] as Kind[]) {
    const m = quiet(); const x = m.distance + 8; put(m, 'pit', x, w);
    const nw = DIMS[next][1]; put(m, next, x + w / 2 / RULES.scale + nw / 2 / RULES.scale + off / 4, nw);
    let landed = false;
    for (let i = 0; i < 120 * 10 && m.phase === 'running'; i++) {
      hold(m, s); const was = m.rescue !== null; m.step(DT);
      if (was && !m.rescue) { landed = true; break; }
    }
    if (!landed) continue;
    checked++; const px = m.distance * RULES.scale;
    for (const i of m.items) if (i.kind !== 'food' && i.kind !== 'gold') {
      const overlap = px + RULES.halfHitWidth > i.x * RULES.scale - i.w / 2 && px - RULES.halfHitWidth < i.x * RULES.scale + i.w / 2;
      assert.equal(overlap, false, `landed inside ${i.kind} (pit ${w}, ${s}, next ${next}, off ${off})`);
    }
    assert.ok(m.grounded);
  }
  console.log(`rescue landings checked: ${checked}`);
  assert.ok(checked > 300, `checked ${checked}`);
});

test('consecutive pits do not trap the player in a rescue loop', () => {
  const m = quiet(); let x = m.distance + 8; for (let k = 0; k < 4; k++) { put(m, 'pit', x, 170); x += 170 / RULES.scale + 0.2; }
  let rescues = 0, was = false;
  for (let i = 0; i < 120 * 20 && m.phase === 'running'; i++) { m.stamina = 80; m.gap = 30; m.step(DT); if (m.rescue && !was) rescues++; was = m.rescue !== null; }
  assert.ok(rescues >= 1 && rescues <= 2, `rescues ${rescues}`); assert.equal(m.phase, 'running'); assert.ok(m.distance > x + 10);
});

test('falling with an empty gap ends the run', () => {
  const m = quiet(); m.gap = 2; put(m, 'pit', m.distance + 2, 120); run(m, 5);
  assert.equal(m.phase, 'over'); assert.equal(m.gap, 0);
});

test('pause freezes a rescue in progress', () => {
  const p = quiet(); put(p, 'pit', p.distance + 2, 120);
  for (let i = 0; i < 120 * 6 && !p.rescue; i++) { p.stamina = 80; p.gap = 30; p.step(DT); }
  assert.ok(p.rescue); p.pause();
  const s = [p.rescue!.time, p.distance, p.y]; for (let i = 0; i < 300; i++) p.step(DT);
  assert.deepEqual([p.rescue!.time, p.distance, p.y], s);
});

// ---------------------------------------------------------------- course generation, seeds, food
test('seeds: default seed is reproducible, the same seed gives the same course, different seeds differ', () => {
  const sig = (m: RunnerModel) => m.items.map(i => `${i.kind}${i.x}`).join(',');
  const a = new RunnerModel(13579, true, GROUND), b = new RunnerModel(13579, true, GROUND);
  assert.equal(sig(a), sig(b));
  const far = (seed: number) => { const m = new RunnerModel(seed, true, GROUND); m.distance = 24 * 400; (m as any).generate(); return sig(m); };
  assert.equal(far(7), far(7)); assert.notEqual(far(7), far(8));
});

function course(seed: number, chunks: number) {
  const m = new RunnerModel(seed, true, GROUND); m.distance = 24 * chunks; /* chunks = distance / 24m (size unit only) */ (m as any).generate();
  const isFood = (i: { kind: string }) => i.kind === 'food' || i.kind === 'gold';
  return { m, chunks, foods: m.items.filter(isFood), hazards: m.items.filter(i => !isFood(i)) };
}
const SEEDS = [13579, 1, 2, 7, 99, 2026, 31337, 424242];

test('contract: obstacle width bounds and food placement constants', () => {
  assert.deepEqual(OBSTACLE_WIDTHS, { block: [48, 64], tower: [44, 52], long: [120, 170], pit: [120, 200], beam: [100, 220] });
  assert.deepEqual([RULES.foodHazardMargin, RULES.minFoodSpacing, RULES.foodLiftMin, RULES.foodLiftMax], [4, 8, 48, 205]);
});

test('difficultyAt: linear ramp, clamped at 1200m (hazard spacing 22->18m, food spacing 24->30m)', () => {
  const at = (d: number) => difficultyAt(d);
  assert.deepEqual([at(0).level, at(0).obstacleSpacing, at(0).foodSpacing], [0, 22, 24]);
  assert.deepEqual([at(600).level, at(600).obstacleSpacing, at(600).foodSpacing], [.5, 20, 27]);
  assert.deepEqual([at(1200).level, at(1200).obstacleSpacing, at(1200).foodSpacing], [1, 18, 30]);
  assert.deepEqual([at(50000).level, at(50000).obstacleSpacing, at(50000).foodSpacing], [1, 18, 30]);
  assert.deepEqual([at(-5).level, at(-5).obstacleSpacing, at(-5).foodSpacing], [0, 22, 24]);
});

test('course: hazards start at 19m and follow the distance-based spacing; they are generated 140m ahead', () => {
  for (const seed of SEEDS) {
    const { hazards } = course(seed, 400);
    assert.equal(hazards[0].x, 19);
    for (let i = 1; i < hazards.length; i++) assert.ok(Math.abs(hazards[i].x - hazards[i - 1].x - difficultyAt(hazards[i - 1].x).obstacleSpacing) < 1e-9, `seed ${seed} #${i}`);
    assert.ok(hazards.at(-1)!.x >= 400 * 24 + 140 - 22 && hazards.at(-1)!.x < 400 * 24 + 140, `last hazard ${hazards.at(-1)!.x}`);
  }
  const m = new RunnerModel(7, true, GROUND); const first = m.items.filter(i => i.kind !== 'food' && i.kind !== 'gold');
  assert.ok(first.at(-1)!.x >= 140 - 22 && first.at(-1)!.x < 140, 'initial course already reaches 140m');
});

test('course: foods follow the scheduled slots (+-4m jitter, spacing >= 8m); unsafe slots are skipped, first food 3..11', () => {
  let slotsTotal = 0, placed = 0, lo = Infinity, hi = -Infinity;
  for (const seed of SEEDS) {
    const D = 40000, { foods } = course(seed, D / 24);
    const slots: number[] = []; for (let d = 7; d < D + 96; d += difficultyAt(d).foodSpacing) slots.push(d);
    assert.ok(foods[0].x >= 3 && foods[0].x <= 11 + 1e-9, `first food ${foods[0].x}`);
    let k = 0;
    for (let n = 0; n < foods.length; n++) {
      while (k < slots.length && slots[k] + 4 + 1e-9 < foods[n].x) k++;
      assert.ok(k < slots.length && Math.abs(foods[n].x - slots[k]) <= 4 + 1e-9, `seed ${seed} food ${n} x ${foods[n].x} slot ${slots[k]}`);
      lo = Math.min(lo, foods[n].x - slots[k]); hi = Math.max(hi, foods[n].x - slots[k]); k++;
      if (n) assert.ok(foods[n].x - foods[n - 1].x >= RULES.minFoodSpacing - 1e-9, `seed ${seed} spacing ${foods[n].x - foods[n - 1].x}`);
    }
    slotsTotal += slots.length; placed += foods.length;
  }
  const skipped = 1 - placed / slotsTotal;
  console.log(`food slots placed ${placed}/${slotsTotal} (skipped ${(skipped * 100).toFixed(1)}%), jitter ${lo.toFixed(2)}..${hi.toFixed(2)}m`);
  assert.ok(lo < -2.5 && hi > 2.5, `jitter really varies: ${lo}..${hi}`);
  assert.ok(skipped < .35, `too many skipped food slots: ${skipped}`);
});

test('course: every food is clear of every hazard (edge + half hit 24 + food half 16 + 4m)', () => {
  let nearest = Infinity;
  for (const seed of SEEDS) {
    const { foods, hazards } = course(seed, 2000);
    for (const f of foods) for (const h of hazards) {
      const dx = Math.abs(f.x - h.x); if (dx > 40) continue;
      const need = h.w / 2 / RULES.scale + (RULES.halfHitWidth + f.w / 2) / RULES.scale + RULES.foodHazardMargin;
      nearest = Math.min(nearest, dx - need);
      assert.ok(dx >= need - 1e-9, `seed ${seed} ${f.kind}@${f.x} vs ${h.kind}@${h.x}w${h.w}: ${dx} < ${need}`);
    }
  }
  console.log(`closest food-to-hazard margin beyond the required distance: ${nearest.toFixed(2)}m`);
});

test('course: food height floor-48..floor-205, roughly uniform', () => {
  const lifts: number[] = [];
  for (const seed of SEEDS) for (const f of course(seed, 2000).foods) { lifts.push(F - f.y); assert.equal(f.h, 32); assert.equal(f.w, 32); }
  assert.ok(Math.min(...lifts) >= 48 - 1e-9 && Math.max(...lifts) <= 205 + 1e-9);
  assert.ok(Math.min(...lifts) < 52 && Math.max(...lifts) > 201, 'range is actually used');
  const mean = lifts.reduce((a, b) => a + b, 0) / lifts.length;
  assert.ok(Math.abs(mean - 126.5) < 3, `mean lift ${mean}`);
});

// A food `lift` px above the floor, 20m ahead; returns true if the player eats it.
function eats(lift: number, state: State, jumpAhead: number | null) {
  const m = quiet(); const x = m.distance + 20;
  m.items.push({ id: 1, x, y: F - lift, w: 32, h: 32, kind: 'food', used: false }); let jumped = false;
  for (let i = 0; i < 120 * 12 && m.distance < x + 3; i++) {
    hold(m, state); const ahead = x - m.distance;
    if (!jumped && jumpAhead !== null && ahead <= jumpAhead) { m.jump(); jumped = true; }
    m.step(DT);
  }
  return m.foods === 1;
}
test('food reach: low food is walkable, high food (up to floor-205) is reachable with ONE jump in every state', () => {
  const walkable = RULES.playerHeight + 32; // the food bottom must pass the player's head
  assert.equal(eats(100, 'normal', null), true); assert.equal(eats(walkable - 4, 'normal', null), true);
  assert.equal(eats(walkable + 6, 'normal', null), false); assert.equal(eats(205, 'normal', null), false);
  for (const state of ['normal', 'exhausted'] as State[]) for (let lift = 48; lift <= 205; lift += 157 / 8) {
    let ok = 0; for (let a = 0.2; a <= 9; a += 0.1) if (eats(lift, state, a)) ok++;
    assert.ok(ok >= 3, `lift ${lift.toFixed(0)} ${state}: only ${ok} timings reach it`);
  }
});

test('course: widths stay inside OBSTACLE_WIDTHS, use the whole range, kinds repeat in the 6-chunk cycle', () => {
  const seen: Record<string, number[]> = {}; const kinds: Record<string, number> = {};
  for (const seed of SEEDS) for (const h of course(seed, 1200).hazards) {
    const [lo, hi] = (OBSTACLE_WIDTHS as any)[h.kind]; assert.ok(h.w >= lo && h.w <= hi, `${h.kind} ${h.w} not in ${lo}..${hi}`);
    (seen[h.kind] ??= []).push(h.w); kinds[h.kind] = (kinds[h.kind] ?? 0) + 1;
  }
  for (const k of Object.keys(OBSTACLE_WIDTHS)) {
    const [lo, hi] = (OBSTACLE_WIDTHS as any)[k], w = seen[k]; assert.ok(w, k);
    assert.ok(Math.min(...w) <= lo + 3 && Math.max(...w) >= hi - 3, `${k} uses ${Math.min(...w)}..${Math.max(...w)}`);
  }
  const total = Object.values(kinds).reduce((a, b) => a + b, 0), unit = total / 6;
  assert.ok(Math.abs(kinds.block / unit - 2) < 0.05 && Math.abs(kinds.beam / unit - 1) < 0.05 && Math.abs(kinds.tower / unit - 1) < 0.05 && Math.abs(kinds.long / unit - 1) < 0.05 && Math.abs(kinds.pit / unit - 1) < 0.05, JSON.stringify(kinds));
  const first = new RunnerModel(13579, true, GROUND).items.filter(i => i.kind !== 'food' && i.kind !== 'gold')[0]; assert.equal(first.kind, 'block');
});

test('course: free distance between neighbouring hazards stays large at the new maximum widths', () => {
  let minLater = Infinity, minFirst = Infinity;
  for (const seed of SEEDS) {
    const hz = course(seed, 1500).hazards;
    for (let i = 1; i < hz.length; i++) {
      const gapM = (hz[i].x - hz[i].w / 2 / RULES.scale) - (hz[i - 1].x + hz[i - 1].w / 2 / RULES.scale);
      if (i === 1) minFirst = Math.min(minFirst, gapM); else minLater = Math.min(minLater, gapM);
    }
  }
  console.log(`min free distance between hazards: first pair ${minFirst.toFixed(1)}m, later pairs ${minLater.toFixed(1)}m`);
  let minCap = Infinity; for (const seed of SEEDS) { const hz = course(seed, 1500).hazards.filter(h => h.x >= 1200); for (let i = 1; i < hz.length; i++) minCap = Math.min(minCap, (hz[i].x - hz[i].w / 2 / RULES.scale) - (hz[i - 1].x + hz[i - 1].w / 2 / RULES.scale)); }
  console.log(`at the 18m cap (>=1200m): min free distance ${minCap.toFixed(1)}m = ${(minCap / RULES.speed).toFixed(2)}s at 6m/s, ${(minCap / RULES.boostSpeed).toFixed(2)}s boosted`);
  assert.ok(minCap >= 12 && minCap / RULES.boostSpeed >= 1.3, `cap ${minCap}`);
  assert.ok(minLater >= 12, `later ${minLater}`); assert.ok(minFirst >= 8, `first ${minFirst}`);
});

test('course: gold is about 1/10 of foods (several seeds), without streak bias', () => {
  for (const seed of [13579, 1, 2026]) {
    const { foods } = course(seed, 10000);
    const gold = foods.filter(i => i.kind === 'gold').length, rate = gold / foods.length;
    assert.ok(Math.abs(rate - RULES.goldChance) < 0.012, `seed ${seed} gold rate ${rate}`);
    let pairs = 0, after = 0; for (let i = 1; i < foods.length; i++) if (foods[i - 1].kind === 'gold') { pairs++; if (foods[i].kind === 'gold') after++; }
    assert.ok(Math.abs(after / pairs - RULES.goldChance) < 0.04, `seed ${seed} gold-after-gold ${after / pairs}`);
  }
});

test('stamina economy: only low foods can be eaten by walking; the rest need a jump', () => {
  const walkable = RULES.playerHeight + 32;
  const range = (lo: number, hi: number) => SEEDS.flatMap(sd => course(sd, 2000).foods.filter(f => f.x >= lo && f.x < hi));
  const early = range(0, 400), late = range(1600, 2000), all = SEEDS.flatMap(sd => course(sd, 2000).foods);
  const walkShare = all.filter(f => F - f.y < walkable).length / all.length;
  const avg = RULES.food * (1 - RULES.goldChance) + RULES.goldFood * RULES.goldChance;
  const perMetre = (foods: unknown[], from: number, to: number) => foods.length / (SEEDS.length * (to - from));
  const income = (density: number, share: number) => avg * share * density * RULES.speed; // per second at 6m/s
  const dEarly = perMetre(early, 0, 400), dLate = perMetre(late, 1600, 2000);
  console.log(`walkable foods ${(walkShare * 100).toFixed(0)}%; foods per 100m: 0-400m ${(dEarly * 100).toFixed(2)}, 1600-2000m ${(dLate * 100).toFixed(2)}; income if all eaten early ${income(dEarly, 1).toFixed(2)}/s, late ${income(dLate, 1).toFixed(2)}/s, walking only (late) ${income(dLate, walkShare).toFixed(2)}/s, drain ${RULES.staminaDrain}/s`);
  assert.ok(Math.abs(walkShare - (walkable - 48) / (205 - 48)) < 0.03, `walk share ${walkShare}`);
  assert.ok(dEarly >= dLate * .95 && dLate > .015, `food does not get denser with distance and never vanishes: ${dEarly} vs ${dLate}`);
  // 4/s drain: fixed recovery no longer makes the course indefinitely sustainable.
  assert.ok(income(dEarly, 1) < RULES.staminaDrain && income(dLate, 1) < RULES.staminaDrain); assert.ok(income(dLate, walkShare) < RULES.staminaDrain);
});

// ---------------------------------------------------------------- reaching 1000m
// Analytic stamina along the real course: drain between foods, +food when eaten (cap 100), no hits, 6m/s.
function reach(seed: number, eatShare: number) {
  const m = new RunnerModel(seed, true, GROUND); m.distance = 1300; (m as any).generate();
  const foods = m.items.filter(i => (i.kind === 'food' || i.kind === 'gold') && i.x <= 1000).sort((a, b) => a.x - b.x);
  let st = 100, x = 0, lowest = 100, taken = 0, k = 0;
  const to = (target: number) => { // drain from x to target; returns the distance where stamina hits 0, or null
    const need = RULES.staminaDrain * (target - x) / RULES.speed;
    if (st - need <= 0) return x + st * RULES.speed / RULES.staminaDrain;
    st -= need; x = target; lowest = Math.min(lowest, st); return null;
  };
  for (const f of foods) {
    const dead = to(f.x); if (dead !== null) return { reach: dead, lowest: 0 };
    k += eatShare; if (Math.floor(k) > taken) { taken++; st = Math.min(100, st + (f.kind === 'gold' ? RULES.goldFood : RULES.food)); }
  }
  const dead = to(1000); // remaining drain up to exactly 1000m
  return dead !== null ? { reach: dead, lowest: 0 } : { reach: 1000, lowest };
}
test('balance: 4/s creates more endurance pressure when foods are missed', () => {
  const seeds = [13579, 1, 2, 7, 99, 2026, 31337, 424242, 11, 12, 13, 14, 15, 16, 17, 18];
  const all = seeds.map(s => reach(s, 1)), most = seeds.map(s => reach(s, .8)), half = seeds.map(s => reach(s, .5));
  const lo = (a: { reach: number }[]) => Math.min(...a.map(r => r.reach));
  console.log(`1000m check over ${seeds.length} seeds: eat all -> min reach ${lo(all).toFixed(0)}m (lowest stamina ${Math.min(...all.map(r => r.lowest)).toFixed(0)}), eat 80% -> ${lo(most).toFixed(0)}m (lowest ${Math.min(...most.map(r => r.lowest)).toFixed(0)}), eat 50% -> ${lo(half).toFixed(0)}m`);
  assert.ok(lo(all) >= lo(most) && lo(most) > lo(half), 'more food extends stamina endurance');
  assert.ok(lo(most) < 1000, 'the former 80% food guarantee no longer holds at 4/s');
  assert.ok(lo(half) < 1000, 'ignoring half the food still hurts');
});
